  21 /// Outcome of a resume copy operation.
  22 #[derive(Debug)]
  23 pub struct ResumeCopyOutcome {
  24     /// Total bytes in the final file.
  25     pub total_bytes: u64,
  26     /// Bytes that were actually transferred (not skipped).
  27     pub bytes_transferred: u64,
  28     /// Number of blocks that matched and were skipped.
  29     pub blocks_skipped: u64,
  30     /// Number of blocks that were transferred.
