  40 /// Copy a file with resume capability using block-level hash comparison.
  41 ///
  42 /// Compares source and destination block-by-block using Blake3 hashes:
  43 /// - Matching blocks (same hash) are skipped
  44 /// - Mismatched blocks are overwritten from source
  45 /// - If source is longer, remaining bytes are appended
  46 /// - If source is shorter, destination is truncated
  47 ///
  48 /// This is efficient for:
  49 /// - Resuming interrupted transfers (partial files)
  50 /// - Updating files with localized changes
  51 /// - Verifying and fixing corrupted copies
  52 pub fn resume_copy_file(src: &Path, dst: &Path, block_size: usize) -> Result<ResumeCopyOutcome> {
  53     let mut src_file =
  54         File::open(src).with_context(|| format!("opening source: {}", src.display()))?;
  55     let src_len = src_file
  56         .metadata()
  57         .with_context(|| format!("reading source metadata: {}", src.display()))?
  58         .len();
  59     resume_copy_from(&mut src_file, src_len, dst, block_size)
