554     /// so its unopenability never makes a mirror deletion unsafe.
555     pub(super) async fn plan_chunk(&self, needed: Vec<FileHeader>) -> Result<Vec<TransferPayload>> {
556         if needed.is_empty() {
557             return Ok(Vec::new());
558         }
559         let payloads = crate::remote::transfer::payload::plan_transfer_payloads(
560             needed,
561             &self.src_root,
562             self.plan_options,
563         )?;
564         for payload in &payloads {
565             match payload {
566                 TransferPayload::TarShard { headers } => {
567                     self.stats.tar_shard_tasks.fetch_add(1, Ordering::Relaxed);
568                     self.stats
569                         .tar_shard_files
