4015 /// Stamp the metadata tail of a resume completion through the descriptor
4016 /// the truncation already holds: named streams and attributes stay
4017 /// path-based (no handle-based Windows ADS/attribute API exists), while
4018 /// mtime and — on Unix — permissions route through `file`. Returns the
4019 /// named-stream bytes applied.
4020 ///
4021 /// The sf-3c treatment applied to the resume-completion path: the prior
4022 /// code dropped the truncation handle and re-addressed `dst` by path for
4023 /// both stamps. `sync_all` on the caller's handle is strictly stronger
4024 /// than the flush sf-3c relies on, and `into_std` waits on the same
4025 /// in-flight-completion check, so stamping through the handle cannot
4026 /// reintroduce the deferred-write mtime race — no write happens after it.
4027 fn stamp_resumed_metadata_via_handle(
4028     file: &std::fs::File,
4029     dst: &Path,
4030     mtime_seconds: i64,
4031     permissions: u32,
4032     windows_metadata: Option<&crate::generated::WindowsFileMetadata>,
4033 ) -> Result<u64> {
4034     run_metadata_tail_fault_hook(dst)?;
4035     let windows_bytes = crate::windows_metadata::replace_streams(dst, windows_metadata)?;
4036     if mtime_seconds > 0 {
4037         let ft = FileTime::from_unix_time(mtime_seconds, 0);
4038         // Best-effort, same as the streamed path: cross-fs, root-owned or
4039         // ACL-protected destinations can refuse the update.
4040         if let Err(e) = filetime::set_file_handle_times(file, None, Some(ft)) {
4041             log::warn!("set mtime on {}: {}", dst.display(), e);
4042         }
4043     }
4044     #[cfg(unix)]
4045     if permissions != 0 {
4046         use std::os::unix::fs::PermissionsExt;
4047         if let Err(e) = file.set_permissions(std::fs::Permissions::from_mode(permissions)) {
4048             log::warn!("set permissions on {}: {}", dst.display(), e);
4049         }
4050     }
4051     #[cfg(not(unix))]
4052     let _ = permissions;
4053     crate::windows_metadata::apply_attributes(dst, windows_metadata)?;
4054     Ok(windows_bytes)
4055 }
