#[cfg(all(test, unix))]
mod review_prepare_before_replace {
    use super::*;
    use std::os::unix::fs::PermissionsExt;

    #[tokio::test]
    async fn local_handle_acquisition_failure_preserves_the_previous_file() {
        let fixture = tempfile::tempdir().unwrap();
        let source = fixture.path().join("source");
        let dest = fixture.path().join("destination");
        std::fs::create_dir(&source).unwrap();
        std::fs::create_dir(&dest).unwrap();
        let name = "clone-fault.bin";
        let target = dest.join(name);
        std::fs::write(source.join(name), b"new data").unwrap();
        std::fs::set_permissions(source.join(name), std::fs::Permissions::from_mode(0o600)).unwrap();
        std::fs::write(&target, b"original").unwrap();
        std::fs::set_permissions(&target, std::fs::Permissions::from_mode(0o644)).unwrap();
        let sink = FsTransferSink::new(source, dest, FsSinkConfig { resume: true, ..Default::default() });
        let header = FileHeader { relative_path: name.into(), size: 8, permissions: 0o100600, ..Default::default() };
        let outcome = sink.write_payload(PreparedPayload::File(header)).await.unwrap();
        assert!(outcome.file_failed(name));
        assert!(outcome.failures.iter().any(|f| f.reason.contains("Too many open files")));
        assert_eq!(std::fs::read(target).unwrap(), b"original");
    }
}
